// Live TV directory generated by tools/build_channels.py from public free-to-air
// iptv-org playlists: adult content removed, duplicates merged, streams re-probed.

export interface Channel {
  id: string;
  name: string;
  logo: string;
  url: string;
  fallbacks: string[];
  country: string;
  category: string;
  quality: string;
}

export const CHANNELS: Channel[] = [];
const MAP = new Map(CHANNELS.map((c) => [c.id, c]));

export function syncChannels(channels: Channel[]): void {
  CHANNELS.splice(0, CHANNELS.length, ...channels);
  MAP.clear();
  CHANNELS.forEach((c) => MAP.set(c.id, c));
  CHANNEL_FILTERS.splice(
    0,
    CHANNEL_FILTERS.length,
    "All",
    ...["Bangladesh", "India"].filter((country) =>
      CHANNELS.some((c) => c.country === country),
    ),
    ...CATEGORY_ORDER.filter((category) =>
      CHANNELS.some((c) => c.category === category),
    ),
  );
}

export function getChannel(id: string): Channel | undefined {
  return MAP.get(id);
}

const CATEGORY_ORDER = [
  "Sports",
  "News",
  "Kids",
  "Movies",
  "Entertainment",
  "Series",
  "Music",
  "Documentary",
  "Education",
  "General",
];
const present = new Set(CHANNELS.map((c) => c.category));

export const CHANNEL_FILTERS: string[] = [
  "All",
  ...(CHANNELS.some((c) => c.country === "Bangladesh") ? ["Bangladesh"] : []),
  ...(CHANNELS.some((c) => c.country === "India") ? ["India"] : []),
  ...CATEGORY_ORDER.filter((c) => present.has(c)),
];

export function filterChannels(filter: string): Channel[] {
  if (filter === "All") return CHANNELS;
  if (filter === "Bangladesh" || filter === "India")
    return CHANNELS.filter((c) => c.country === filter);
  return CHANNELS.filter((c) => c.category === filter);
}

export function searchChannels(query: string, limit = 30): Channel[] {
  const terms = query.trim().toLowerCase().split(/\s+/).filter(Boolean);
  if (terms.length === 0) return [];
  return CHANNELS.map((c) => ({
    channel: c,
    haystack: `${c.name}|${c.category}|${c.country}`.toLowerCase(),
  }))
    .filter((e) => terms.every((t) => e.haystack.includes(t)))
    .slice(0, limit)
    .map((e) => e.channel);
}

/** Next/previous channel within the same list, for zapping in the live player. */
export function neighbor(
  list: Channel[],
  id: string,
  step: 1 | -1,
): Channel | undefined {
  const i = list.findIndex((c) => c.id === id);
  if (i < 0 || list.length === 0) return undefined;
  return list[(i + step + list.length) % list.length];
}
